using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private StatusStrip _statusStrip;

    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);

        // .NET 9 breaking change: StatusStrip no longer auto-applies the
        // system renderer. Set it explicitly to preserve the previous look.
        _statusStrip = new StatusStrip();
        _statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Shows a dropdown editor for a control value.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control dropdown)
    {
        // .NET 9 breaking change: DropDownControl now throws
        // ArgumentNullException when passed null.
        if (dropdown is null)
            return;

        editorService.DropDownControl(dropdown);
    }

    // .NET 9 breaking change: use LibraryImport (source-generated P/Invoke)
    // instead of the legacy DllImport for better performance and trimming support.
    [LibraryImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    internal static partial bool SetForegroundWindow(IntPtr hWnd);

    [LibraryImport("user32.dll", EntryPoint = "MessageBoxW", StringMarshalling = StringMarshalling.Utf16)]
    internal static partial int MessageBox(IntPtr hWnd, string text, string caption, uint type);
}

